// Werte kommen aus dem Node "⚙️ Konfiguration" (Flow-Context).
// Falls dort nichts gesetzt ist, greifen diese Fallback-Werte.
// -- Values come from the "⚙️ Konfiguration" node (flow context).
// -- If nothing is set there, these fallback values are used.
const homeLat = flow.get('homeLat') ?? 48.137;
const homeLon = flow.get('homeLon') ?? 11.575;
const radiusNm = flow.get('radiusNm') ?? 5; // Umkreis - je kleiner, desto genauer "über dem Haus" / search radius - smaller = more precisely "overhead"

// Backoff bei Rate-Limit (429): solange nicht abgelaufen, keine neue Anfrage senden.
// Wird von "Neue Flugzeuge filtern" gesetzt, wenn adsb.lol mit 429 antwortet.
// -- Backoff on rate limit (429): don't send a new request until this expires.
// -- Set by "Neue Flugzeuge filtern" whenever adsb.lol responds with 429.
const rateLimitedUntil = flow.get('adsbRateLimitedUntil') || 0;
if (Date.now() < rateLimitedUntil) {
    const waitSec = Math.ceil((rateLimitedUntil - Date.now()) / 1000);
    node.status({ fill: "yellow", shape: "ring", text: `rate limited, warte noch ${waitSec}s / waiting ${waitSec}s` });
    return null; // diesen Zyklus überspringen / skip this cycle
}
node.status({});

// adsb.lol verlangt einen aussagekräftigen User-Agent mit echter Kontaktmöglichkeit,
// sonst kommt statt JSON nur "User-Agent too generic; include valid contact info." zurück.
// TODO: Trage hier eine echte Kontaktmöglichkeit ein (E-Mail oder z.B. dein GitHub-Profil).
// -- adsb.lol requires a meaningful User-Agent with real contact info, otherwise it
// -- returns "User-Agent too generic; include valid contact info." instead of JSON.
// -- TODO: Put a real contact here (email address or e.g. your GitHub profile).
msg.headers = {
    'User-Agent': 'NodeRED-FlightDisplay/1.0 (+contact: DEINE-EMAIL@BEISPIEL.DE)'
};

msg.url = `https://api.adsb.lol/v2/point/${homeLat}/${homeLon}/${radiusNm}`;
return msg;

// Erst den HTTP-Statuscode prüfen: bei 429 (Rate-Limit) sofort Backoff setzen,
// statt zu versuchen, die HTML-Fehlerseite als JSON zu parsen.
// -- Check the HTTP status code first: on 429 (rate limit) set a backoff
// -- immediately instead of trying to parse the HTML error page as JSON.
if (msg.statusCode && msg.statusCode !== 200) {
    if (msg.statusCode === 429) {
        const backoffMs = 5 * 60 * 1000; // 5 Minuten Pause / 5 minute pause
        flow.set('adsbRateLimitedUntil', Date.now() + backoffMs);
        node.warn('adsb.lol: 429 Too Many Requests - pausiere Anfragen für 5 Minuten / pausing requests for 5 minutes');
        node.status({ fill: "red", shape: "dot", text: "429 - backoff aktiv / active" });
    } else {
        node.warn(`adsb.lol antwortete mit Status ${msg.statusCode} / adsb.lol responded with status ${msg.statusCode}`);
        node.status({ fill: "red", shape: "dot", text: `HTTP ${msg.statusCode}` });
    }
    return null;
}

// Antwort selbst parsen statt vom http-request-Node automatisch parsen zu lassen.
// Grund: adsb.lol liefert bei Rate-Limit/fehlendem User-Agent/Wartung manchmal einen
// Fehlertext statt JSON zurück - mit automatischem Parsen (ret:'obj') bricht der Node
// dann mit "JSON parse error" ab und der ganze Zyklus geht verloren. So läuft der
// Flow beim nächsten Mal einfach weiter.
// -- We parse the response ourselves instead of letting the http-request node parse
// -- it automatically. Reason: adsb.lol sometimes returns a plain error text instead
// -- of JSON (rate limit, missing User-Agent, maintenance). With automatic parsing
// -- (ret:'obj') the node would then crash with "JSON parse error" and the whole
// -- cycle would be lost. This way the flow just continues on the next run.
let data;
try {
    data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('ADS-B Antwort war kein gültiges JSON (evtl. Rate-Limit/fehlender User-Agent/Wartung bei adsb.lol): ' + String(msg.payload).slice(0, 200));
    // -- ADS-B response was not valid JSON (possibly rate limit / missing User-Agent / adsb.lol maintenance)
    return null;
}
node.status({ fill: "green", shape: "dot", text: `${(data && data.ac && data.ac.length) || 0} Flugzeuge / aircraft` });

const seen = flow.get('seenAircraft') || {};
const now = Date.now();
const cooldownMinutes = flow.get('cooldownMinutes') ?? 10;
const cooldownMs = cooldownMinutes * 60 * 1000; // Sperre pro Flugzeug / cooldown per aircraft

for (const hex in seen) {
    if (now - seen[hex] > cooldownMs) delete seen[hex];
}

const aircraft = (data && data.ac) || [];
const msgs = [];

for (const ac of aircraft) {
    if (!ac.alt_baro || ac.alt_baro === "ground") continue; // nur Flugzeuge in der Luft / airborne aircraft only
    if (!ac.hex || seen[ac.hex]) continue;

    const callsign = (ac.flight || "").trim();
    if (!callsign) continue;

    seen[ac.hex] = now;
    msgs.push({ aircraftInfo: { callsign, altitude: ac.alt_baro, hex: ac.hex } });
}

flow.set('seenAircraft', seen);
return [msgs.length ? msgs : null];

// Auch adsbdb.com bekommt vorsorglich einen echten User-Agent mit, falls die API
// künftig ebenso strikt prüft wie adsb.lol.
// -- We also send a real User-Agent to adsbdb.com as a precaution, in case that API
// -- starts enforcing it as strictly as adsb.lol does.
msg.headers = {
    'User-Agent': 'NodeRED-FlightDisplay/1.0 (+contact: DEINE-EMAIL@BEISPIEL.DE)'
};
msg.url = `https://api.adsbdb.com/v0/callsign/${msg.aircraftInfo.callsign}`;
return msg;

// --- Flaggen als 8x8-Pixel-Icons (vereinfachte Näherung, keine Pixel-perfekten Flaggen) ---
// --- Flags as 8x8 pixel icons (simplified approximation, not pixel-perfect flags) ---
function stripesH(colors) {
    const cmds = []; let y = 0;
    colors.forEach((c, i) => {
        const yEnd = Math.round(8 * (i + 1) / colors.length);
        cmds.push(["rectFill", 0, y, 8, yEnd - y, c]);
        y = yEnd;
    });
    return cmds;
}
function stripesV(colors) {
    const cmds = []; let x = 0;
    colors.forEach((c, i) => {
        const xEnd = Math.round(8 * (i + 1) / colors.length);
        cmds.push(["rectFill", x, 0, xEnd - x, 8, c]);
        x = xEnd;
    });
    return cmds;
}
function nordicCross(bg, cross) {
    return [["rectFill", 0, 0, 8, 8, bg], ["rectFill", 0, 3, 8, 2, cross], ["rectFill", 2, 0, 2, 8, cross]];
}
function swissCross() {
    return [["rectFill", 0, 0, 8, 8, "#FF0000"], ["rectFill", 1, 3, 6, 2, "#FFFFFF"], ["rectFill", 3, 1, 2, 6, "#FFFFFF"]];
}
function turkeyFlag() {
    return [["rectFill", 0, 0, 8, 8, "#E30A17"], ["circleFill", 3, 4, 2, "#FFFFFF"], ["circleFill", 4, 4, 2, "#E30A17"], ["pixel", 6, 3, "#FFFFFF"]];
}
function ukFlag() {
    return [["rectFill", 0, 0, 8, 8, "#00247D"], ["rectFill", 0, 3, 8, 2, "#FFFFFF"], ["rectFill", 3, 0, 2, 8, "#FFFFFF"], ["rectFill", 0, 3, 8, 1, "#CF142B"], ["rectFill", 3, 0, 1, 8, "#CF142B"]];
}

const FLAGS = {
    DE: stripesH(["#000000", "#DD0000", "#FFCC00"]),
    TR: turkeyFlag(),
    ES: stripesH(["#AA151B", "#F1BF00", "#AA151B"]),
    FR: stripesV(["#0055A4", "#FFFFFF", "#EF4135"]),
    IT: stripesV(["#009246", "#FFFFFF", "#CE2B37"]),
    GB: ukFlag(),
    NL: stripesH(["#AE1C28", "#FFFFFF", "#21468B"]),
    PL: stripesH(["#FFFFFF", "#DC143C"]),
    AT: stripesH(["#ED2939", "#FFFFFF", "#ED2939"]),
    CH: swissCross(),
    GR: stripesH(["#0D5EAF", "#FFFFFF", "#0D5EAF", "#FFFFFF", "#0D5EAF"]),
    PT: stripesV(["#046A38", "#DA291C"]),
    BE: stripesV(["#000000", "#FAE042", "#ED2939"]),
    SE: nordicCross("#006AA7", "#FECC00"),
    NO: nordicCross("#EF2B2D", "#FFFFFF"),
    DK: nordicCross("#C60C30", "#FFFFFF"),
    FI: nordicCross("#FFFFFF", "#003580"),
    IE: stripesV(["#169B62", "#FFFFFF", "#FF883E"]),
    CZ: stripesH(["#FFFFFF", "#D7141A"]),
    HR: stripesH(["#FF0000", "#FFFFFF", "#171796"]),
    US: stripesH(["#B22234", "#FFFFFF", "#3C3B6E"]),
    EG: stripesH(["#CE1126", "#FFFFFF", "#000000"]),
    MA: [["rectFill", 0, 0, 8, 8, "#C1272D"], ["pixel", 4, 4, "#006233"]]
};

// --- eigentliche Payload-Erstellung ---
// --- actual payload construction ---
// Antwort selbst parsen (siehe 'ret':'txt' am Node), damit eine kaputte/nicht-JSON
// Antwort von adsbdb.com den Flow nicht mit "JSON parse error" abbrechen lässt.
// -- Parse the response ourselves (see 'ret':'txt' on the node) so a broken/non-JSON
// -- response from adsbdb.com doesn't crash the flow with "JSON parse error".
let apiResponse;
try {
    apiResponse = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('adsbdb Antwort war kein gültiges JSON: ' + String(msg.payload).slice(0, 200));
    // -- adsbdb response was not valid JSON
    return null;
}

const info = msg.aircraftInfo || {};
const callsign = info.callsign || "?";
const route = apiResponse && apiResponse.response && apiResponse.response.flightroute;

if (!route) {
    return null;
}

const originCity = route.origin ? (route.origin.municipality || route.origin.iata_code) : "?";
const originIso = route.origin && route.origin.country_iso_name;
const destCity = route.destination ? (route.destination.municipality || route.destination.iata_code) : "?";
const destIso = route.destination && route.destination.country_iso_name;

const originLabel = originIso ? `${originCity} (${originIso})` : originCity;
const destLabel = destIso ? `${destCity} (${destIso})` : destCity;

const textFragments = [
    { text: callsign, color: "#FFCC00" },
    { text: " | ", color: "#666666" },
    { text: `${originLabel} -> ${destLabel}`, color: "#FFFFFF" }
];

let draw = [], textOffsetX = 0;
if (destIso && FLAGS[destIso]) {
    draw = FLAGS[destIso];
    textOffsetX = 9;
}

// Werte kommen aus dem Node "⚙️ Konfiguration" (Flow-Context), mit Fallbacks.
// -- Values come from the "⚙️ Konfiguration" node (flow context), with fallbacks.
const awtrixTopic = flow.get('awtrixTopic') ?? "AWTRIX-xyz123/cmd/notify";
const durationMs = flow.get('durationMs') ?? 50000;
const soundEnabled = flow.get('soundEnabled') ?? true;
const soundRtttl = flow.get('soundRtttl') ?? "beep:d=4,o=6,b=200:16c";
const quietHoursStart = flow.get('quietHoursStart') ?? 22;
const quietHoursEnd = flow.get('quietHoursEnd') ?? 9;

// Nachtruhe -> kein Piepton / quiet hours -> no beep
const hour = new Date().getHours();
const isQuietHours = (hour >= quietHoursStart || hour < quietHoursEnd);

msg.topic = awtrixTopic;
msg.payload = {
    text: textFragments,
    draw: draw,
    textOffsetX: textOffsetX,
    durationMs: durationMs,
    stack: true
};

if (soundEnabled && !isQuietHours) {
    msg.payload.soundRtttl = soundRtttl;
}

return msg;
